"""规则配置留在环境；数据库只保存规则指纹、风险与证据引用。"""

import hashlib
import json
from dataclasses import dataclass
from datetime import datetime
from uuid import UUID

from pydantic import Field, field_validator, model_validator
from sqlalchemy import Boolean, CheckConstraint, ForeignKey, Integer, String, UniqueConstraint
from sqlalchemy.orm import Mapped, mapped_column

from app.connectors.kubernetes.models import ServiceName
from app.db.base import Base, UTCDateTime
from app.tasks.inspection.catalog import BY_ID, Area, Category, Mode, Outcome
from app.tasks.workflow_models import TaskSnapshot
from app.tools.models import ToolModel


class InspectionConfig(ToolModel):
    enabled: bool = True
    services: tuple[ServiceName, ...] = Field(
        default=("payment-service",), min_length=1, max_length=20
    )
    max_age_seconds: int = Field(default=900, ge=1, le=86400)
    thresholds: dict[str, float] = Field(default_factory=dict)

    @model_validator(mode="after")
    def valid(self) -> "InspectionConfig":
        import math

        if len(set(self.services)) != len(self.services):
            raise ValueError("巡检范围不能重复")
        for key, value in self.thresholds.items():
            if (
                key not in BY_ID
                or BY_ID[key].operator not in {"min", "max"}
                or not math.isfinite(value)
            ):
                raise ValueError("巡检阈值必须对应数值检查且为有限值")
        return self

    @property
    def fingerprint(self) -> str:
        return hashlib.sha256(
            json.dumps(self.model_dump(mode="json"), sort_keys=True).encode()
        ).hexdigest()


class CheckResult(ToolModel):
    service_name: ServiceName
    check_id: str
    resource: str
    area: Area
    category: Category
    label: str
    outcome: Outcome
    evidence_id: UUID | None
    source_reference: str | None
    observed_at: datetime | None
    assessed_at: datetime
    reason: str

    @field_validator("observed_at", "assessed_at")
    @classmethod
    def utc(cls, value: datetime | None) -> datetime | None:
        return UTCDateTime.normalize(value)


class InspectionReport(ToolModel):
    task_id: UUID
    phase_version: int = Field(ge=1)
    mode: Mode
    rule_fingerprint: str = Field(pattern=r"^[0-9a-f]{64}$")
    checks: tuple[CheckResult, ...]
    runbook_evidence_ids: tuple[UUID, ...]

    @property
    def complete(self) -> bool:
        return bool(self.checks) and all(item.outcome != "unknown" for item in self.checks)


class RiskEntry(Base):
    __tablename__ = "inspection_risks"
    __table_args__ = (
        UniqueConstraint("risk_key"),
        CheckConstraint("risk_key ~ '^[0-9a-f]{64}$'", name="key_valid"),
        CheckConstraint(
            "category IN ('stability','capacity','security','cost')", name="category_valid"
        ),
        CheckConstraint("outcome IN ('abnormal','unknown')", name="outcome_valid"),
        CheckConstraint("episode >= 1 AND last_seen >= first_seen", name="observation_valid"),
    )
    risk_key: Mapped[str] = mapped_column(String(64), nullable=False)
    service_name: Mapped[str] = mapped_column(String(63), nullable=False)
    check_id: Mapped[str] = mapped_column(String(64), nullable=False)
    resource: Mapped[str] = mapped_column(String(256), nullable=False)
    category: Mapped[str] = mapped_column(String(16), nullable=False)
    outcome: Mapped[str] = mapped_column(String(16), nullable=False)
    active: Mapped[bool] = mapped_column(Boolean, nullable=False)
    episode: Mapped[int] = mapped_column(Integer, nullable=False)
    first_seen: Mapped[datetime] = mapped_column(UTCDateTime(), nullable=False)
    last_seen: Mapped[datetime] = mapped_column(UTCDateTime(), nullable=False)
    cleared_at: Mapped[datetime | None] = mapped_column(UTCDateTime())
    opening_evidence_id: Mapped[UUID] = mapped_column(
        ForeignKey("evidence_ledger.id"), nullable=False
    )
    latest_evidence_id: Mapped[UUID] = mapped_column(
        ForeignKey("evidence_ledger.id"), nullable=False
    )
    notification_evidence_id: Mapped[UUID | None] = mapped_column(ForeignKey("evidence_ledger.id"))


def risk_key(value: CheckResult) -> str:
    return hashlib.sha256(
        json.dumps(
            [value.service_name, value.check_id, value.resource], separators=(",", ":")
        ).encode()
    ).hexdigest()


@dataclass(frozen=True)
class InspectionRequest:
    task: TaskSnapshot
    mode: Mode


@dataclass(frozen=True)
class InspectionResult:
    evidence_id: str
    report_json: str
    risk_ids: list[str]


@dataclass(frozen=True)
class InspectionVerifyRequest:
    task: TaskSnapshot
    report_evidence_id: str


class InspectionVerification(ToolModel):
    task_id: UUID
    verifying_version: int
    report_evidence_id: UUID
    passed: bool

"""认知与运营控制台的输入和投影契约。"""

import json
from datetime import UTC, datetime, timedelta
from typing import Any, Literal, Self
from uuid import UUID

from pydantic import AwareDatetime, Field, JsonValue, field_validator, model_validator

from app.db.base import utc_now
from app.knowledge.schemas import KnowledgeDraft
from app.ledger.models import AuditEventType
from app.runbooks.schemas import RunbookContent
from app.tasks.console_models import ConsoleModel, EventView, EvidenceView, TaskView

Center = Literal[
    "releases", "tickets", "inspections", "war-rooms", "architecture-reviews", "automations"
]
AuditKind = AuditEventType | Literal["catalog_edit"]


class TimeWindow(ConsoleModel):
    start: AwareDatetime = Field(default_factory=lambda: utc_now() - timedelta(days=30))
    end: AwareDatetime = Field(default_factory=utc_now)

    @field_validator("start", "end")
    @classmethod
    def utc(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)

    @model_validator(mode="after")
    def ordered(self) -> Self:
        if self.start >= self.end:
            raise ValueError("开始时间必须早于结束时间")
        return self


class KnowledgeInput(KnowledgeDraft):
    @model_validator(mode="before")
    @classmethod
    def wire(cls, value: Any) -> Any:
        if isinstance(value, dict):
            return KnowledgeDraft.model_validate_json(json.dumps(value)).model_dump()
        return value


class RunbookInput(RunbookContent):
    @model_validator(mode="before")
    @classmethod
    def wire(cls, value: Any) -> Any:
        if isinstance(value, dict):
            return RunbookContent.model_validate_json(json.dumps(value)).model_dump()
        return value


class ChangeEntryView(ConsoleModel):
    id: UUID
    service_name: str
    source: str
    kind: str
    source_ref: str
    revision: str | None
    occurred_at: datetime
    created_at: datetime


class ScenarioView(ConsoleModel):
    task: TaskView
    event: EventView


class ScenarioDetail(ScenarioView):
    # 每条快照保留真实 ID、来源及 UTC 时间，阶段未完成时不伪造报告。
    evidence: list[EvidenceView]


class RiskView(ConsoleModel):
    id: UUID
    service_name: str
    check_id: str
    resource: str
    category: str
    outcome: str
    active: bool
    episode: int
    first_seen: datetime
    last_seen: datetime
    cleared_at: datetime | None
    opening_evidence_id: UUID
    latest_evidence_id: UUID
    notification_evidence_id: UUID | None


class AuditView(ConsoleModel):
    id: UUID
    task_id: UUID | None
    event_type: AuditKind
    actor: str
    operation: str
    outcome: str
    evidence_id: UUID | None
    details: dict[str, JsonValue]
    occurred_at: datetime

"""规划草稿与宿主判定结果；均不包含执行权限或凭证。"""

from dataclasses import dataclass
from typing import Annotated
from uuid import UUID

from pydantic import Field, StringConstraints, field_validator, model_validator

from app.agent.investigation import EvidenceClaim, Text
from app.policy.models import (
    PolicyDecision,
    PolicyEnvironment,
    PolicyResult,
    RiskLevel,
    RunbookPolicyContext,
)
from app.tasks.workflow_models import TaskSnapshot
from app.tools.models import JsonObject, ToolModel, ToolName

Identifier = Annotated[str, StringConstraints(pattern=r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$")]


class RollbackPlan(ToolModel):
    description: Text
    parameters: Annotated[JsonObject, Field(min_length=1)]
    trigger: Text


class VerificationPlan(ToolModel):
    checks: Annotated[tuple[Text, ...], Field(min_length=1, max_length=20)]
    success_criteria: Text
    failure_response: Text


class RollbackParameters(ToolModel):
    from_version: Identifier
    to_version: Identifier

    @model_validator(mode="after")
    def different_versions(self) -> "RollbackParameters":
        if self.from_version == self.to_version:
            raise ValueError("回滚的起始与目标版本不能相同")
        return self


class PlannedAction(ToolModel):
    id: Identifier
    name: ToolName
    service_name: Identifier
    parameters: Annotated[JsonObject, Field(min_length=1)]
    risk_level: RiskLevel = RiskLevel.L5
    rationale: EvidenceClaim
    preconditions: Annotated[tuple[Text, ...], Field(min_length=1, max_length=20)]
    rollback: RollbackPlan
    verification: VerificationPlan

    @field_validator("risk_level", mode="before")
    @classmethod
    def undeclared_risk(cls, value: object) -> object:
        return RiskLevel.L5 if value is None else value

    @model_validator(mode="after")
    def rollback_parameters(self) -> "PlannedAction":
        if self.name == "rollback_prod":
            RollbackParameters.model_validate(self.parameters)
        return self


class ActionPlanDraft(ToolModel):
    summary: EvidenceClaim
    actions: Annotated[tuple[PlannedAction, ...], Field(min_length=1, max_length=10)]

    @model_validator(mode="after")
    def unique_actions(self) -> "ActionPlanDraft":
        if len({action.id for action in self.actions}) != len(self.actions):
            raise ValueError("计划中的动作 ID 不可重复")
        return self


class EvaluatedAction(ToolModel):
    action: PlannedAction
    policy: PolicyResult

    @model_validator(mode="after")
    def aligned(self) -> "EvaluatedAction":
        if (self.action.name, self.action.risk_level) != (
            self.policy.action_name,
            self.policy.risk_level,
        ):
            raise ValueError("Policy 判定必须对应同一动作和宿主风险等级")
        return self


class ActionPlan(ToolModel):
    task_id: UUID
    planning_version: int = Field(ge=1)
    conclusion_evidence_id: UUID
    review_evidence_id: UUID
    environment: PolicyEnvironment
    summary: EvidenceClaim
    actions: Annotated[tuple[EvaluatedAction, ...], Field(min_length=1, max_length=10)]
    runbook: RunbookPolicyContext | None = Field(
        default=None, exclude_if=lambda value: value is None
    )

    @property
    def decision(self) -> PolicyDecision:
        for decision in (PolicyDecision.DENY, PolicyDecision.NEED_APPROVAL):
            if any(item.policy.decision is decision for item in self.actions):
                return decision
        return PolicyDecision.ALLOW


@dataclass(frozen=True)
class PlanningRequest:
    task: TaskSnapshot
    spec_json: str
    conclusion_evidence_id: str
    review_evidence_id: str


@dataclass(frozen=True)
class PlanningResult:
    evidence_id: str
    plan_json: str

"""发布 Activity 组合根，Timer、重试和审批暂停仍由统一 Workflow 控制。"""

import json
from datetime import timedelta
from uuid import UUID

from temporalio import activity

from app.agent.activities import lock_task
from app.agent.investigation import InvestigationSpec
from app.config import Settings
from app.connectors.changes.releases import FakeReleaseState
from app.db.base import utc_now
from app.db.session import Database
from app.executor.models import ExecutionRequest, ExecutionResult
from app.executor.releases import ReleaseExecutor
from app.ledger.service import LedgerService
from app.runbooks.activities import RunbookActivities
from app.runbooks.workflow_models import RunbookMatchRequest, RunbookMatchResult
from app.tasks.planning.models import PlanningResult
from app.tasks.releases.models import (
    ReleaseManifest,
    ReleaseObserveRequest,
    ReleaseObserveResult,
    ReleasePlanRequest,
    ReleaseStageRequest,
)
from app.tasks.releases.service import ReleaseStore
from app.tasks.states import TaskStatus
from app.tasks.tickets.service import cached
from app.tasks.workflow_models import TaskSnapshot
from app.tools.models import JsonObject
from app.tools.registry import json_object
from app.verifier.releases import ReleaseVerifier


class ReleaseActivities:
    def __init__(
        self, database: Database, settings: Settings, *, state: FakeReleaseState | None = None
    ) -> None:
        self.state = state or FakeReleaseState()
        self.store = ReleaseStore(database, settings, self.state)
        self.executor = ReleaseExecutor(database, settings, self.state)
        self.verifier = ReleaseVerifier(database, settings, self.state)

    @activity.defn(name="release.match_runbook")
    async def match_runbook(self, request: ReleaseStageRequest) -> RunbookMatchResult:
        async with self.store.database.session() as session, session.begin():
            task = await lock_task(session, request.task)
            record = await self.store.read(
                session,
                task.id,
                "get_release_request",
                {"release_id": request.release_id},
                "workflow",
            )
            manifest = ReleaseManifest.model_validate_json(json.dumps(record.result_snapshot))
        now = utc_now()
        spec = InvestigationSpec(
            service_name=manifest.service_name,
            title="发布预检查 " + request.release_id,
            start=now - timedelta(seconds=1),
            end=now,
            max_steps=20,
        )
        return await RunbookActivities(self.store.database, self.store.settings).match(
            RunbookMatchRequest(request.task, spec.model_dump_json())
        )

    @activity.defn(name="release.read_assessment")
    async def read_assessment(self, evidence_id: str) -> str:
        async with self.store.database.session() as session:
            record = await LedgerService(session).get_evidence(UUID(evidence_id))
            if record.source_tool != "release.assessment":
                raise ValueError("不是发布检查证据")
            return json.dumps(record.result_snapshot)

    @activity.defn(name="release.assess")
    async def assess(self, request: ReleaseStageRequest) -> str:
        return await self.store.assess(request)

    @activity.defn(name="release.review")
    async def review(self, request: ReleasePlanRequest) -> str:
        return await self.store.review(request)

    @activity.defn(name="release.plan")
    async def plan(self, request: ReleasePlanRequest) -> PlanningResult:
        return await self.store.plan(request)

    @activity.defn(name="release.execute")
    async def execute(self, request: ExecutionRequest) -> ExecutionResult:
        return await self.executor.execute(request)

    @activity.defn(name="release.observe")
    async def observe(self, request: ReleaseObserveRequest) -> ReleaseObserveResult:
        return await self.verifier.observe(request)

    @activity.defn(name="release.report")
    async def report(self, snapshot: TaskSnapshot) -> str:
        async with self.store.database.session() as session, session.begin():
            task = await lock_task(session, snapshot)
            if task.status is not TaskStatus.LEARNING:
                raise ValueError("发布报告必须在独立验证后进入 LEARNING")
            key: JsonObject = {"phase_version": task.status_version}
            ledger = LedgerService(session)
            previous = await cached(session, task.id, "release.report", key)
            if previous:
                return str(previous.id)
            records = await ledger.evidence_for_task(task.id)
            assessments = [e for e in records if e.source_tool == "release.assessment"]
            proofs = [e for e in records if e.source_tool == "verify_release"]
            if not assessments or not proofs:
                raise ValueError("发布报告缺少检查和独立验证")
            from app.verifier.releases import ReleaseVerification

            last = ReleaseVerification.model_validate_json(json.dumps(proofs[-1].result_snapshot))
            if not last.final or not last.passed:
                raise ValueError("未恢复的发布不能生成成功报告")
            report = {
                "task_id": str(task.id),
                "outcome": "rolled_back"
                if any(e.parameters.get("name") == "rollback_prod" for e in records)
                else "released",
                "checks": assessments[0].result_snapshot,
                "evidence_ids": [
                    str(e.id)
                    for e in records
                    if e.source_tool
                    in {
                        "release.assessment",
                        "release.review",
                        "action_plan",
                        "approval.request",
                        "approval.decision",
                        "execute_action",
                        "verify_release",
                    }
                ],
                "timeline": [
                    {
                        "evidence_id": str(e.id),
                        "source": e.source_tool,
                        "collected_at": e.collected_at.isoformat(),
                    }
                    for e in records
                    if e.source_tool
                    in {
                        "release.assessment",
                        "release.review",
                        "action_plan",
                        "approval.request",
                        "approval.decision",
                        "execute_action",
                        "verify_release",
                    }
                ],
            }
            evidence = await ledger.append_evidence(
                task_id=UUID(snapshot.task_id),
                source_tool="release.report",
                parameters=key,
                result_snapshot=json_object(report),
            )
            return str(evidence.id)

"""发布检查、灰度目标和观测窗口；配置只由环境提供。"""

import hashlib
import json
from dataclasses import dataclass
from datetime import UTC, datetime
from typing import Literal
from uuid import UUID

from pydantic import AwareDatetime, Field, field_validator, model_validator

from app.agent.investigation import EvidenceClaim
from app.executor.models import ExecutionTarget
from app.policy.models import RiskLevel
from app.tasks.planning.models import Identifier
from app.tasks.workflow_models import TaskSnapshot
from app.tools.models import ToolModel

Purpose = Literal["canary", "promote", "pause", "rollback"]


class ReleaseConfig(ToolModel):
    enabled: bool = False
    canary_percent: int = Field(default=10, ge=1, lt=100)
    observation_seconds: float = Field(default=60, gt=0, le=3600, allow_inf_nan=False)
    max_5xx_ratio: float = Field(default=0.01, ge=0, lt=1, allow_inf_nan=False)
    max_p99_ms: float = Field(default=500, gt=0, allow_inf_nan=False)
    min_success_ratio: float = Field(default=0.99, gt=0, le=1, allow_inf_nan=False)


class DeployParameters(ToolModel):
    from_version: Identifier
    to_version: Identifier
    traffic_percent: int = Field(ge=1, le=100)


class ReleaseQuery(ToolModel):
    release_id: Identifier


class ReleaseManifest(ToolModel):
    release_id: Identifier
    service_name: Identifier
    from_version: Identifier
    to_version: Identifier
    sql: tuple[str, ...]
    resource_ready: bool
    monitoring_ready: bool
    rollback_ready: bool
    reference: str = Field(min_length=1)

    @model_validator(mode="after")
    def different_versions(self) -> "ReleaseManifest":
        if self.from_version == self.to_version:
            raise ValueError("发布必须改变版本")
        return self


def manifest_hash(value: ReleaseManifest) -> str:
    return hashlib.sha256(
        json.dumps(value.model_dump(mode="json"), sort_keys=True).encode()
    ).hexdigest()


class ReleaseWindow(ReleaseQuery):
    start: AwareDatetime
    end: AwareDatetime

    @field_validator("start", "end")
    @classmethod
    def utc_times(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)

    @model_validator(mode="after")
    def window(self) -> "ReleaseWindow":
        if not 0 < (self.end - self.start).total_seconds() <= 3600:
            raise ValueError("发布观测窗口必须为 0–3600 秒")
        return self


class ReleaseObservation(ReleaseWindow):
    service_name: Identifier
    target: ExecutionTarget
    deployment_ready: bool
    pods_ready: bool
    http_5xx: tuple[float, ...]
    p99_ms: tuple[float, ...]
    success_ratio: tuple[float, ...]
    logs_healthy: bool
    traces_healthy: bool
    resources_healthy: bool

    @field_validator("http_5xx", "p99_ms", "success_ratio")
    @classmethod
    def finite_samples(cls, values: tuple[float, ...]) -> tuple[float, ...]:
        import math

        if any(not math.isfinite(v) or v < 0 for v in values):
            raise ValueError("指标必须是有限非负值")
        return values

    @model_validator(mode="after")
    def same_service(self) -> "ReleaseObservation":
        if self.target.service_name != self.service_name or any(
            v > 1 for v in (*self.http_5xx, *self.success_ratio)
        ):
            raise ValueError("发布观测服务或比例值不合法")
        return self


class ReleaseCheck(ToolModel):
    name: Literal["git_diff", "impact", "sql", "resources", "monitoring", "rollback"]
    passed: bool
    risk_level: RiskLevel = RiskLevel.L0
    claim: EvidenceClaim


class ReleaseAssessment(ToolModel):
    task_id: UUID
    phase_version: int
    manifest: ReleaseManifest
    manifest_hash: str = Field(pattern=r"^[0-9a-f]{64}$")
    purpose: Purpose
    checks: tuple[ReleaseCheck, ...]
    canary_percent: int
    config_hash: str = Field(pattern=r"^[0-9a-f]{64}$")

    @model_validator(mode="after")
    def complete_checks(self) -> "ReleaseAssessment":
        if (
            len(self.checks) != 6
            or {c.name for c in self.checks}
            != {"git_diff", "impact", "sql", "resources", "monitoring", "rollback"}
            or self.manifest_hash != manifest_hash(self.manifest)
        ):
            raise ValueError("发布检查必须覆盖六项，且材料指纹一致")
        return self

    @property
    def passed(self) -> bool:
        return len(self.checks) == 6 and all(c.passed for c in self.checks)


@dataclass(frozen=True)
class ReleaseStageRequest:
    task: TaskSnapshot
    release_id: str
    purpose: Purpose = "canary"


@dataclass(frozen=True)
class ReleasePlanRequest:
    task: TaskSnapshot
    assessment_evidence_id: str
    review_evidence_id: str | None = None


@dataclass(frozen=True)
class ReleaseObserveRequest:
    task: TaskSnapshot
    release_id: str
    start: str
    end: str
    plan_evidence_id: str
    final: bool = False


@dataclass(frozen=True)
class ReleaseObserveResult:
    task: TaskSnapshot
    evidence_id: str
    passed: bool
    report_json: str

"""Temporal 分离持久化熔断与通知；先停动作，再重试发送固定身份的接管通知。"""

from uuid import NAMESPACE_URL, UUID, uuid5

from sqlalchemy import select
from temporalio import activity
from temporalio.exceptions import ApplicationError

from app.config import Settings
from app.connectors.feishu.base import FeishuConnector
from app.connectors.feishu.factory import create_feishu_connector
from app.connectors.feishu.models import TextNotification
from app.db.session import Database
from app.ledger.models import AuditEventType
from app.ledger.service import LedgerService
from app.tasks.models import AITask
from app.tasks.safety.models import REASON_TEXT, AbortReason, SafetyResult
from app.tasks.safety.service import SafetyStore, abort_record
from app.tasks.workflow_models import TaskSnapshot
from app.tools.registry import json_object


class SafetyActivities:
    def __init__(
        self, database: Database, settings: Settings, *, connector: FeishuConnector | None = None
    ) -> None:
        self.database, self.settings, self.connector = database, settings, connector
        self.store = SafetyStore(database, settings.safety_config)

    @activity.defn(name="safety.check")
    async def check(self, snapshot: TaskSnapshot) -> SafetyResult:
        try:
            return await self.store.check(snapshot)
        except (ValueError, LookupError, TypeError):
            raise ApplicationError("熔断检查版本或证据被拒绝", non_retryable=True) from None

    @activity.defn(name="safety.notify")
    async def notify(self, task_id: str) -> str:
        connector = self.connector or create_feishu_connector(self.settings)
        try:
            return await self.send_notification(task_id, connector)
        finally:
            if self.connector is None:
                await connector.aclose()

    async def send_notification(self, task_id: str, connector: FeishuConnector) -> str:
        async with self.database.session() as session, session.begin():
            task = await session.scalar(
                select(AITask).where(AITask.id == UUID(task_id)).with_for_update()
            )
            record = await abort_record(session, UUID(task_id))
            if task is None or record is None or not isinstance(record.result_snapshot, dict):
                raise ApplicationError("接管通知必须引用已提交的熔断证据", non_retryable=True)
            ledger = LedgerService(session)
            previous = next(
                (
                    e
                    for e in await ledger.evidence_for_task(task.id)
                    if e.source_tool == "safety.notification"
                ),
                None,
            )
            if previous is not None:
                return str(previous.id)
            reasons = record.result_snapshot["reasons"]
            assert isinstance(reasons, list)
            explanation = "、".join(REASON_TEXT[AbortReason(str(r))] for r in reasons)
            notification = TextNotification(
                notification_id=uuid5(NAMESPACE_URL, f"safety/{task.id}/{record.id}"),
                text=(
                    f"自动化已熔断，请人工接管\n任务：{task.id}\n原因：{explanation}\n"
                    f"熔断 Evidence ID：{record.id}\n后续动作已阻止，旧审批不能恢复自动执行。"
                ),
            )
            receipt = await connector.send(notification)
            evidence = await ledger.append_evidence(
                task_id=task.id,
                source_tool="safety.notification",
                parameters={"abort_evidence_id": str(record.id)},
                result_snapshot={
                    "notification": json_object(notification.model_dump(mode="json")),
                    "receipt": json_object(receipt.model_dump(mode="json")),
                },
            )
            await ledger.append_audit(
                task_id=task.id,
                event_type=AuditEventType.EXECUTION,
                actor="workflow",
                operation="safety.notify",
                outcome="sent",
                evidence_id=evidence.id,
                details={
                    "abort_evidence_id": str(record.id),
                    "notification_id": str(notification.notification_id),
                },
            )
            return str(evidence.id)

"""只计算同任务已提交事实，不查询系统、不迁移状态、不重试。"""

import json
from collections import defaultdict
from datetime import datetime
from uuid import UUID

from app.agent.reviewer.models import ReviewDecision
from app.runbooks.schemas import RunbookView
from app.tasks.safety.models import (
    AbortReason,
    AuditFact,
    EvidenceFact,
    SafetyConfig,
    SafetyFinding,
)
from app.tools.models import DispatchStatus
from app.tools.observability import MetricsInput, MetricsOutput, TracesOutput, WindowInput
from app.verifier.models import VerificationReport


def evaluate(
    evidence: list[EvidenceFact],
    audits: list[AuditFact],
    config: SafetyConfig,
    *,
    pending_action: tuple[str, str] | None = None,
) -> tuple[SafetyFinding, ...]:
    config = SafetyConfig.model_validate(config)
    evidence = sorted(evidence, key=lambda e: (e.collected_at, str(e.id)))
    audits = sorted(audits, key=lambda a: (a.occurred_at, str(a.id)))
    findings: list[SafetyFinding] = []
    failures: list[UUID] = []
    for audit in audits:
        if audit.operation != "execute_action" or audit.details.get("mode") != "live":
            continue
        if audit.outcome == "succeeded":
            failures.clear()
        elif audit.outcome == "failed":
            failures.append(audit.id)
    if len(failures) >= config.max_consecutive_execution_failures:
        findings.append(
            SafetyFinding(reason=AbortReason.EXECUTION_FAILURES, audit_ids=tuple(failures))
        )

    by_id = {e.id: e for e in evidence}
    successful = {
        a.evidence_id
        for a in audits
        if a.outcome == DispatchStatus.SUCCEEDED.value
        and a.details.get("mode") == "live"
        and a.evidence_id in by_id
        and by_id[a.evidence_id].source == a.operation
    }
    metrics: dict[
        tuple[str, str, str], list[tuple[EvidenceFact, tuple[tuple[datetime, float], ...]]]
    ] = defaultdict(list)
    impacts: dict[str, list[tuple[EvidenceFact, datetime, datetime, frozenset[str]]]] = defaultdict(
        list
    )
    for fact in evidence:
        if fact.id not in successful:
            continue
        if fact.source == "query_release_observation":
            from app.tasks.releases.models import ReleaseObservation

            observed = ReleaseObservation.model_validate_json(json.dumps(fact.result))
            for release_values, threshold, delta, direction in (
                (observed.http_5xx, config.max_5xx_ratio, config.min_5xx_increase, 1),
                (observed.p99_ms, config.max_p99_ms, config.min_p99_increase_ms, 1),
                (observed.success_ratio, config.min_success_ratio, config.min_success_decrease, -1),
            ):
                directed = tuple(v * direction for v in release_values)
                if (
                    len(directed) >= config.min_metric_points
                    and directed[-1] > threshold * direction
                    and directed[-1] - directed[0] >= delta
                    and all(b >= a for a, b in zip(directed, directed[1:], strict=False))
                ):
                    findings.append(
                        SafetyFinding(reason=AbortReason.METRICS_WORSENING, evidence_ids=(fact.id,))
                    )
        if fact.source == "query_metrics":
            data = MetricsOutput.model_validate_json(json.dumps(fact.result))
            query = MetricsInput.model_validate_json(json.dumps(fact.parameters))
            if (data.service_name, data.start, data.end) != (
                query.service_name,
                query.start,
                query.end,
            ):
                continue
            for series in data.series:
                if (
                    series.service_name != data.service_name
                    or series.metric_name != query.metric_name
                ):
                    continue
                points = tuple(
                    sorted(
                        (p.timestamp, p.value) for p in series.points if data.contains(p.timestamp)
                    )
                )
                if len(points) < config.min_metric_points or len({p[0] for p in points}) != len(
                    points
                ):
                    continue
                if any(
                    (b[0] - a[0]).total_seconds() > config.max_sample_gap_seconds
                    for a, b in zip(points, points[1:], strict=False)
                ):
                    continue
                key = (
                    data.service_name,
                    series.metric_name,
                    json.dumps(series.labels, sort_keys=True),
                )
                metrics[key].append((fact, points))
        elif fact.source == "query_traces":
            trace_data = TracesOutput.model_validate_json(json.dumps(fact.result))
            query_window = WindowInput.model_validate_json(json.dumps(fact.parameters))
            if (trace_data.service_name, trace_data.start, trace_data.end) != (
                query_window.service_name,
                query_window.start,
                query_window.end,
            ):
                continue
            affected = frozenset(
                span.service_name
                for trace in trace_data.traces
                if trace.service_name == trace_data.service_name
                and trace_data.contains(trace.timestamp)
                for span in trace.spans
                if trace_data.contains(span.timestamp)
                and (
                    span.result_code.startswith("5")
                    or span.result_code in {"ERROR", "error", "timeout"}
                )
            )
            impacts[trace_data.service_name].append(
                (fact, trace_data.start, trace_data.end, affected)
            )

    rules = {
        "http_5xx_ratio": (1, config.max_5xx_ratio, config.min_5xx_increase),
        "http_p99_ms": (1, config.max_p99_ms, config.min_p99_increase_ms),
        "http_success_ratio": (-1, config.min_success_ratio, config.min_success_decrease),
    }
    for (_, metric, _), samples in metrics.items():
        if metric not in rules:
            continue
        direction, threshold, delta = rules[metric]
        samples.sort(key=lambda item: item[1][-1][0])
        for fact, points in samples:
            values = [p[1] * direction for p in points]
            if (
                values[-1] > threshold * direction
                and values[-1] - values[0] >= delta
                and all(b >= a for a, b in zip(values, values[1:], strict=False))
            ):
                findings.append(
                    SafetyFinding(reason=AbortReason.METRICS_WORSENING, evidence_ids=(fact.id,))
                )
                break
        else:
            # 只有相同服务/指标/标签、互不重叠的真实采样才可跨窗口比较。
            if len(samples) >= 2:
                old, new = samples[0], samples[-1]
                if old[1][-1][0] < new[1][0][0]:
                    baseline = sum(p[1] for p in old[1]) / len(old[1])
                    current = sum(p[1] for p in new[1]) / len(new[1])
                    if (
                        current * direction > threshold * direction
                        and (current - baseline) * direction >= delta
                    ):
                        findings.append(
                            SafetyFinding(
                                reason=AbortReason.METRICS_WORSENING,
                                evidence_ids=(old[0].id, new[0].id),
                            )
                        )
    for windows in impacts.values():
        windows.sort(key=lambda item: item[2])
        for prior, latest in zip(windows, windows[1:], strict=False):
            if prior[2] <= latest[1] and latest[3] > prior[3]:
                findings.append(
                    SafetyFinding(
                        reason=AbortReason.IMPACT_EXPANDING,
                        evidence_ids=(prior[0].id, latest[0].id),
                    )
                )
                break

    for fact in evidence:
        if fact.source != "reviewer.verdict":
            continue
        decision = ReviewDecision.model_validate_json(json.dumps(fact.result))
        references = decision.report.evidence_ids
        if (
            decision.report.verdict == "contradicted"
            and references <= successful
            and any(
                e.id == decision.conclusion_evidence_id and e.source == "agent.conclusion"
                for e in evidence
            )
        ):
            findings.append(
                SafetyFinding(
                    reason=AbortReason.EVIDENCE_CONFLICT,
                    evidence_ids=(
                        fact.id,
                        decision.conclusion_evidence_id,
                        *sorted(references, key=str),
                    ),
                )
            )

    # 计数以匹配后的每次独立诊断/验证为单位，Activity 重投、多个失败步骤不重复计数。
    matches: list[tuple[int, RunbookView, UUID]] = []
    outcomes: dict[UUID, list[tuple[bool, tuple[UUID, ...]]]] = defaultdict(list)
    seen_attempts: set[tuple[UUID, str, int]] = set()
    for fact in evidence:
        if (
            fact.source == "runbook.match"
            and fact.result.get("runbook_json") is not None
            and fact.result.get("blocked") is False
        ):
            guide = RunbookView.model_validate_json(str(fact.result["runbook_json"]))
            matches.append((int(str(fact.parameters["phase_version"])), guide, fact.id))
        elif fact.source in {"agent.observe", "verify_action"} and matches:
            if fact.source == "agent.observe":
                phase = int(str(fact.parameters["phase_version"]))
                failed = fact.result.get("status") == "failed"
                if not failed or not any(
                    str(a.id) == fact.result.get("audit_id") and a.outcome == "failed"
                    for a in audits
                ):
                    continue
                attempt_type = "diagnosis"
            else:
                if fact.id not in successful:
                    continue
                report = VerificationReport.model_validate_json(json.dumps(fact.result))
                phase, failed, attempt_type = (
                    report.spec.verifying_version,
                    not report.passed,
                    "verification",
                )
            candidates = [m for m in matches if m[0] < phase]
            if not candidates:
                continue
            _, guide, match_id = max(candidates, key=lambda m: m[0])
            attempt = (guide.id, attempt_type, phase)
            if attempt not in seen_attempts:
                seen_attempts.add(attempt)
                outcomes[guide.id].append((failed, (fact.id, match_id)))
    for results in outcomes.values():
        consecutive: list[tuple[UUID, ...]] = []
        for failed, outcome_references in results:
            if not failed:
                consecutive.clear()
            else:
                consecutive.append(outcome_references)
        if len(consecutive) >= config.max_consecutive_runbook_failures:
            findings.append(
                SafetyFinding(
                    reason=AbortReason.RUNBOOK_FAILURES,
                    evidence_ids=tuple(dict.fromkeys(r for refs in consecutive for r in refs)),
                )
            )

    intents = {
        (str(e.parameters.get("plan_evidence_id")), str(e.parameters.get("action_id"))): e.id
        for e in evidence
        if e.source == "execution.intent"
    }
    count = len(intents) + int(pending_action is not None and pending_action not in intents)
    if count > config.max_actions:
        findings.append(
            SafetyFinding(reason=AbortReason.ACTION_LIMIT, evidence_ids=tuple(intents.values()))
        )
    # 保留六种独立原因，每种首次判据即可；报告始终引用真实证据/失败调用审计。
    return tuple({f.reason: f for f in reversed(findings)}.values())

"""任务锁下留证和停止自动化；通知失败不回滚熔断，持久化锁存不自动复位。"""

from uuid import UUID

from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession

from app.db.session import Database
from app.ledger.models import AuditEventType, Evidence
from app.ledger.service import LedgerService
from app.tasks.models import AITask
from app.tasks.safety.engine import evaluate
from app.tasks.safety.models import (
    REASON_TEXT,
    AuditFact,
    AutomationAborted,
    EvidenceFact,
    SafetyConfig,
    SafetyResult,
    config_hash,
)
from app.tasks.service import TaskService, TaskStateConflict
from app.tasks.states import ALLOWED_TRANSITIONS, TaskStatus
from app.tasks.workflow_models import TaskSnapshot
from app.tools.registry import json_object


async def abort_record(session: AsyncSession, task_id: UUID) -> Evidence | None:
    records = await session.scalars(
        select(Evidence).where(Evidence.task_id == task_id, Evidence.source_tool == "safety.abort")
    )
    return records.one_or_none()


async def require_automation_active(session: AsyncSession, task_id: UUID) -> None:
    from app.tasks.takeover import takeover_record

    if await takeover_record(session, task_id) is not None:
        raise AutomationAborted("人工已接管，后续自动动作被禁止")
    if await abort_record(session, task_id) is not None:
        raise AutomationAborted("任务已自动熔断，必须由人工接管；旧审批不能恢复自动执行")


class SafetyService:
    def __init__(self, session: AsyncSession, config: SafetyConfig) -> None:
        self.session, self.config = session, SafetyConfig.model_validate(config)

    async def check(
        self, task: AITask, *, pending_action: tuple[str, str] | None = None
    ) -> SafetyResult:
        if not self.session.in_transaction():
            raise RuntimeError("熔断服务需要外层事务")
        # 公共入口也持有行锁，与 Executor 签发和 TaskService 迁移串行化。
        locked = await self.session.scalar(
            select(AITask)
            .where(AITask.id == task.id)
            .with_for_update()
            .execution_options(populate_existing=True)
        )
        if locked is None:
            raise TaskStateConflict("熔断任务不存在")
        task = locked
        ledger = LedgerService(self.session)
        cached = await abort_record(self.session, task.id)
        snapshot = TaskSnapshot(str(task.id), task.status, task.status_version)
        if cached is not None:
            assert isinstance(cached.result_snapshot, dict)
            reasons = cached.result_snapshot["reasons"]
            assert isinstance(reasons, list)
            return SafetyResult(snapshot, str(cached.id), tuple(str(r) for r in reasons))
        if TaskStatus.AUTOMATION_ABORTED not in ALLOWED_TRANSITIONS[task.status]:
            return SafetyResult(snapshot)
        evidence = [
            EvidenceFact(e.id, e.source_tool, e.parameters, e.result_snapshot, e.collected_at)
            for e in await ledger.evidence_for_task(task.id)
            if isinstance(e.result_snapshot, dict)
        ]
        audits = [
            AuditFact(a.id, a.operation, a.outcome, a.occurred_at, a.evidence_id, a.details)
            for a in await ledger.audits_for_task(task.id)
            if a.event_type is AuditEventType.TOOL_CALL
        ]
        findings = evaluate(evidence, audits, self.config, pending_action=pending_action)
        if not findings:
            return SafetyResult(snapshot)
        record = await ledger.append_evidence(
            task_id=task.id,
            source_tool="safety.abort",
            parameters={
                "phase_version": task.status_version,
                "pending_action": list(pending_action) if pending_action else None,
            },
            result_snapshot={
                "reasons": [f.reason.value for f in findings],
                "findings": [json_object(f.model_dump(mode="json")) for f in findings],
                "config_hash": config_hash(self.config),
            },
        )
        explanation = "、".join(REASON_TEXT[f.reason] for f in findings)
        updated = await TaskService(self.session).transition(
            task.id,
            TaskStatus.AUTOMATION_ABORTED,
            expected_status=snapshot.status,
            expected_version=snapshot.version,
            reason=f"自动熔断：{explanation}；证据 {record.id}",
        )
        await ledger.append_audit(
            task_id=task.id,
            event_type=AuditEventType.EXECUTION,
            actor="workflow",
            operation="safety.abort",
            outcome="aborted",
            evidence_id=record.id,
            details={"reasons": [f.reason.value for f in findings]},
        )
        return SafetyResult(
            TaskSnapshot(str(task.id), updated.status, updated.status_version),
            str(record.id),
            tuple(f.reason.value for f in findings),
        )


class SafetyStore:
    def __init__(self, database: Database, config: SafetyConfig) -> None:
        self.database, self.config = database, config

    async def check(self, snapshot: TaskSnapshot) -> SafetyResult:
        async with self.database.session() as session, session.begin():
            task = await session.scalar(
                select(AITask).where(AITask.id == UUID(snapshot.task_id)).with_for_update()
            )
            if task is None:
                raise TaskStateConflict("熔断任务不存在")
            if await abort_record(session, task.id) is None and (
                task.status,
                task.status_version,
            ) != (snapshot.status, snapshot.version):
                raise TaskStateConflict("熔断检查版本已变化")
            return await SafetyService(session, self.config).check(task)

"""工单 Activity 注册；重试与人工暂停由统一 Temporal Workflow 负责。"""

import json
from uuid import UUID

from temporalio import activity

from app.agent.activities import lock_task
from app.agent.investigation import AgentConclusion, InvestigationResult
from app.agent.workflow_models import ConclusionRequest
from app.config import Settings
from app.connectors.ops_platform.tickets import TicketState
from app.db.session import Database
from app.executor.tickets import TicketExecutor
from app.learning.tickets import TicketLearning
from app.ledger.service import LedgerService
from app.tasks.planning.models import PlanningResult
from app.tasks.states import TaskStatus
from app.tasks.tickets.models import (
    TicketAnalysisRequest,
    TicketExecutionRequest,
    TicketPlanRequest,
    TicketStageRequest,
    TicketVerifyRequest,
    TicketVerifyResult,
)
from app.tasks.tickets.service import TicketStore, make_ticket_plan
from app.tools.models import DispatchResult
from app.tools.registry import json_object
from app.verifier.tickets import TicketVerifier


class TicketActivities:
    def __init__(
        self, database: Database, settings: Settings, *, state: TicketState | None = None
    ) -> None:
        state = state or TicketState()
        self.store = TicketStore(database, settings, state)
        self.executor = TicketExecutor(database, settings, state)
        self.verifier = TicketVerifier(database, settings, state)
        self.learning = TicketLearning(database, settings, state)

    @activity.defn(name="ticket.prepare")
    async def prepare(self, value: TicketStageRequest) -> str:
        return await self.store.prepare(value)

    @activity.defn(name="ticket.investigate")
    async def investigate(self, value: TicketAnalysisRequest) -> InvestigationResult:
        return await self.store.investigate(value)

    @activity.defn(name="ticket.conclude")
    async def conclude(self, request: ConclusionRequest) -> str:
        if request.task.status is not TaskStatus.RCA:
            raise ValueError("工单结论必须在 RCA")
        async with self.store.database.session() as session, session.begin():
            task = await lock_task(session, request.task)
            ledger = LedgerService(session)
            records = await ledger.evidence_for_task(task.id)
            observed = sorted(
                (
                    e
                    for e in records
                    if e.source_tool == "ticket.agent.observe"
                    and e.parameters.get("phase_version") == task.status_version - 1
                ),
                key=lambda e: int(str(e.parameters["step"])),
            )
            ids = [
                str(r.evidence_id)
                for e in observed
                if (
                    r := DispatchResult.model_validate_json(json.dumps(e.result_snapshot))
                ).evidence_id
            ]
            conclusion = AgentConclusion.model_validate_json(request.result.conclusion_json)
            audits = await ledger.audits_for_task(task.id)
            if ids != request.result.observed_ids or not conclusion.evidence_ids <= {
                UUID(i) for i in ids
            }:
                raise ValueError("工单结论引用未观察或伪造证据")
            for reference in conclusion.evidence_ids:
                fact = await ledger.get_evidence(reference)
                if fact.task_id != task.id or not any(
                    a.evidence_id == reference
                    and a.actor == "codex-main-agent"
                    and a.operation == fact.source_tool
                    and a.outcome == "succeeded"
                    for a in audits
                ):
                    raise ValueError("工单结论缺少成功查询审计")
            previous = [
                e
                for e in records
                if e.source_tool == "ticket.conclusion"
                and e.parameters.get("phase_version") == task.status_version
            ]
            if previous:
                if previous[0].result_snapshot != conclusion.model_dump(mode="json"):
                    raise ValueError("工单结论重投发生冲突")
                return str(previous[0].id)
            evidence = await ledger.append_evidence(
                task_id=task.id,
                source_tool="ticket.conclusion",
                parameters={"phase_version": task.status_version},
                result_snapshot=json_object(conclusion.model_dump(mode="json")),
            )
            return str(evidence.id)

    @activity.defn(name="ticket.review")
    async def review(self, value: TicketPlanRequest) -> str:
        return await self.store.review(value)

    @activity.defn(name="ticket.plan")
    async def plan(self, value: TicketPlanRequest) -> PlanningResult:
        async with self.store.database.session() as session, session.begin():
            return await make_ticket_plan(session, self.store.settings, value)

    @activity.defn(name="ticket.execute")
    async def execute(self, value: TicketExecutionRequest) -> str:
        return await self.executor.execute(value)

    @activity.defn(name="ticket.verify")
    async def verify(self, value: TicketVerifyRequest) -> TicketVerifyResult:
        return await self.verifier.verify(value)

    @activity.defn(name="ticket.learn")
    async def learn(self, value: TicketStageRequest) -> str:
        return await self.learning.learn(value)

